CREATE TABLE installation (id boolean PRIMARY KEY DEFAULT true CHECK(id), configured boolean NOT NULL DEFAULT false);
INSERT INTO installation VALUES (true,false);
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, admin boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
CREATE TABLE spaces (id uuid PRIMARY KEY, title jsonb NOT NULL, currency text NOT NULL, timezone text NOT NULL, personal boolean NOT NULL, version integer NOT NULL DEFAULT 1, wrapped_key jsonb NOT NULL, key_version text NOT NULL);
CREATE TABLE members (space_id uuid NOT NULL REFERENCES spaces(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','editor','reader')), PRIMARY KEY(space_id,user_id));
CREATE UNIQUE INDEX one_owner_per_space ON members(space_id) WHERE role='owner';
CREATE TABLE records (id uuid PRIMARY KEY, space_id uuid NOT NULL REFERENCES spaces(id), resource text NOT NULL CHECK(resource IN ('categories','expenses','incomes','recurrences','investments','movements','valuations')), payload jsonb NOT NULL, version integer NOT NULL DEFAULT 1, category_id uuid, investment_id uuid, recurrence_id uuid, occurrence_date date, date date, effective_date date, status text, type text, deleted_at timestamptz, deletion_reason text, created_by uuid NOT NULL REFERENCES users(id), updated_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(space_id,id), UNIQUE(recurrence_id,occurrence_date), FOREIGN KEY(space_id,category_id) REFERENCES records(space_id,id), FOREIGN KEY(space_id,investment_id) REFERENCES records(space_id,id), FOREIGN KEY(space_id,recurrence_id) REFERENCES records(space_id,id));
CREATE INDEX records_period ON records(space_id,resource,date) WHERE deleted_at IS NULL;
CREATE INDEX records_effective ON records(space_id,resource,effective_date) WHERE deleted_at IS NULL;
CREATE INDEX records_investment ON records(space_id,investment_id,date) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX valuation_per_day ON records(space_id,investment_id,date) WHERE resource='valuations' AND deleted_at IS NULL;
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE api_keys (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, token_hash text NOT NULL UNIQUE, grants jsonb NOT NULL, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invites (token_hash text PRIMARY KEY, space_id uuid NOT NULL REFERENCES spaces(id), role text NOT NULL CHECK(role IN ('editor','reader')), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE resets (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE audits (id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), key_id uuid REFERENCES api_keys(id), space_id uuid REFERENCES spaces(id), resource text, record_id uuid, operation text NOT NULL, result text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotencies (actor_id uuid NOT NULL REFERENCES users(id), key_id text NOT NULL, token text NOT NULL, request_hash text NOT NULL, space_id uuid NOT NULL REFERENCES spaces(id), record_id uuid NOT NULL REFERENCES records(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,key_id,token));
